def evaluate(sign_in, policies):
    required_controls = set()
    for policy in policies:
        if "risk_levels" in policy and sign_in.get("risk") not in policy["risk_levels"]:
            continue
        if "apps" in policy and sign_in.get("app") not in policy["apps"]:
            continue
        if "locations" in policy and sign_in.get("location") not in policy["locations"]:
            continue
        if policy["block"]:
            return "bloqueado", set()
        required_controls |= policy["controls"]
    decision = "concedido" if not required_controls else "concedido con controles"
    return decision, required_controls

policies = [
    {"name": "Bloquear apps heredadas", "apps": {"legacy-imap"}, "block": True, "controls": set()},
    {"name": "MFA en riesgo alto", "risk_levels": {"high"}, "block": False, "controls": {"mfa"}},
    {"name": "Dispositivo conforme fuera de oficina", "locations": {"untrusted"}, "block": False,
     "controls": {"compliant_device"}},
]

sign_ins = [
    {"user": "ada@example.com", "app": "sharepoint", "risk": "low", "location": "trusted"},
    {"user": "ada@example.com", "app": "sharepoint", "risk": "high", "location": "untrusted"},
    {"user": "ada@example.com", "app": "legacy-imap", "risk": "low", "location": "trusted"},
]

for sign_in in sign_ins:
    decision, controls = evaluate(sign_in, policies)
    print(sign_in["app"], "|", decision, "|", sorted(controls))
